/** Every event name and its `payload`, as the `{seq, event, payload}` frames carry them. */
export interface HostEvents {
  "assistant-tasks-changed": {
    revision: number;
    workspaceId: string;
  };
  "personal-changed": {
    assistantId: string;
    revision: number;
  };
  "pty-data": {
    cursor: number;
    data: string;
    id: string;
  };
  "pty-exit": {
    code?: number | null;
    id: string;
  };
  "pty-renamed": {
    id: string;
    name: string;
  };
  "quit-requested": number;
  "room-event": {
    event: RoomEvent;
    recovery_seq?: number | null;
    room: string;
  };
  "room-runner-changed": {
    room: string;
    snapshot?: RunnerSnapshot | null;
  };
  "session-changed": unknown;
  "settings-changed": unknown;
  "thread-catalog-changed": Record<string, never>;
}
export type HostEventName = keyof HostEvents;

